//! `Resource`：全局单例资源 trait 与资源槽存储。
//! 每个资源槽是类型擦除的 `Arc<RwLock<R>>`；`Res<T>`/`ResMut<T>` 是持有式
//! 守卫，可跨越 await 持有。资源键 [`ResourceId`] 是布局代码经 SHA-256
//! 哈希后截断至 128 位的值，布局代码由 derive 宏生成。
//!
//! `Resource`: global singleton resource trait plus resource slot storage.
//! Each resource slot is a type-erased `Arc<RwLock<R>>`; `Res<T>`/`ResMut<T>`
//! are owned guards that may be held across await. The resource key
//! [`ResourceId`] is the layout code hashed with SHA-256 truncated to 128
//! bits; the layout code is generated by the derive macro.

use parking_lot::RwLock;
use std::any::Any;
use std::collections::HashMap;
use std::fmt;
use std::sync::Arc;
pub use sc_ecs_macros::Resource;

/// 唯一的资源 ID：布局代码经 SHA-256 哈希后截断至 128 位。
///
/// Unique resource ID: layout code hashed with SHA-256, truncated to 128 bits.
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub struct ResourceId(pub [u8; 16]);

impl ResourceId {
    /// 从布局代码导出 ID。
    ///
    /// Derives the ID from layout code.
    ///
    /// - `layout`: 布局代码字符串
    pub fn from_layout(layout: &str) -> Self {
        use sha2::{Digest, Sha256};
        let mut hasher = Sha256::new();
        hasher.update(layout.as_bytes());
        let digest = hasher.finalize();
        let mut id = [0u8; 16];
        id.copy_from_slice(&digest[..16]);
        Self(id)
    }
}

/// 进程级的「布局代码 -> ResourceId」缓存。
///
/// 注意：泛型函数内的 `static OnceLock` 不按单态化实例隔离（所有实例共享
/// 同一个 static），因此必须以完整布局字符串为缓存键来隔离类型。
///
/// Process-level cache from layout code to ResourceId. Note: a `static` inside
/// a generic function is shared by all monomorphized instances, so the full
/// layout string is the cache key that isolates types.
///
/// - `layout`: 布局代码字符串
pub fn cached_resource_id(layout: &str) -> ResourceId {
    use std::collections::HashMap;
    use std::sync::{OnceLock, PoisonError, RwLock};
    static CACHE: OnceLock<RwLock<HashMap<String, ResourceId>>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| RwLock::new(HashMap::new()));
    if let Some(id) = cache.read().unwrap_or_else(PoisonError::into_inner).get(layout) {
        return *id;
    }
    let id = ResourceId::from_layout(layout);
    cache
        .write()
        .unwrap_or_else(PoisonError::into_inner)
        .insert(layout.to_string(), id);
    id
}

/// 以本地具体类型为键缓存派生出的资源 ID；ID 本身始终由规范布局代码构建。
///
/// `TypeId` 只是进程内的缓存键，绝不作为资源 ID 使用。
///
/// Caches a derived resource ID by the local concrete type; the ID is always
/// built from the canonical layout code. `TypeId` is only a process-local
/// memo key, never the resource ID.
///
/// - `build_layout`: 惰性构建规范布局代码的闭包
pub fn cached_resource_id_for<T: 'static>(build_layout: impl FnOnce() -> String) -> ResourceId {
    use std::any::TypeId;
    use std::collections::HashMap;
    use std::sync::{OnceLock, PoisonError, RwLock};
    static CACHE: OnceLock<RwLock<HashMap<TypeId, ResourceId>>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| RwLock::new(HashMap::new()));
    let type_id = TypeId::of::<T>();
    if let Some(id) = cache
        .read()
        .unwrap_or_else(PoisonError::into_inner)
        .get(&type_id)
    {
        return *id;
    }

    let id = ResourceId::from_layout(&build_layout());
    let mut cache = cache.write().unwrap_or_else(PoisonError::into_inner);
    *cache.entry(type_id).or_insert(id)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::{AtomicUsize, Ordering};

    struct CacheProbe;

    #[test]
    fn cached_resource_id_for_skips_layout_formatting_after_first_lookup() {
        let builds = AtomicUsize::new(0);
        let first = cached_resource_id_for::<CacheProbe>(|| {
            builds.fetch_add(1, Ordering::SeqCst);
            "CacheProbe{field:u32}".to_string()
        });
        let second = cached_resource_id_for::<CacheProbe>(|| {
            builds.fetch_add(1, Ordering::SeqCst);
            "CacheProbe{field:u32}".to_string()
        });
        assert_eq!(first, second);
        assert_eq!(first, ResourceId::from_layout("CacheProbe{field:u32}"));
        assert_eq!(builds.load(Ordering::SeqCst), 1);
    }

    struct HostProbe;
    struct PluginProbe;

    #[test]
    fn local_type_id_key_does_not_change_canonical_layout_id() {
        let host = cached_resource_id_for::<HostProbe>(|| "SharedLayout{x:u32}".into());
        let plugin = cached_resource_id_for::<PluginProbe>(|| "SharedLayout{x:u32}".into());
        assert_eq!(host, plugin);
    }
}

impl fmt::Debug for ResourceId {
    /// 以 `ResourceId(十六进制)` 形式输出资源 id。
    ///
    /// Formats the resource id as `ResourceId(hex)`.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let hex: String = self.0.iter().map(|b| format!("{b:02x}")).collect();
        write!(f, "ResourceId({hex})")
    }
}

/// 资源 trait：所有全局单例资源的基础接口。
///
/// Resource trait: the base interface of every global singleton resource.
pub trait Resource {
    /// 由布局派生的唯一 ID（由 derive 宏从结构体布局代码计算；泛型实例化
    /// 带有运行时 `type_name` 后缀，见 `sc_ecs_macros::Resource` 文档）。
    ///
    /// Layout-derived unique ID (computed by the derive macro from the struct
    /// layout code; generic instantiations carry a runtime `type_name` suffix,
    /// see the `sc_ecs_macros::Resource` docs).
    fn resource_id() -> ResourceId
    where
        Self: Sized;

    /// 返回资源的运行时名称。
    ///
    /// Returns the runtime name of the resource.
    fn name() -> String
    where
        Self: Sized;
}

/// 每个资源槽是一个 `Arc<RwLock<R>>`（类型擦除后存放）。
/// `Res<T>`/`ResMut<T>` 持有持有式 arc 守卫，可跨线程与 await 保持有效。
///
/// Each resource slot is an `Arc<RwLock<R>>` (stored type-erased).
/// `Res<T>`/`ResMut<T>` hold owned arc guards that stay valid across threads
/// and await.
pub struct ResourceManager {
    /// 资源槽表：按 `ResourceId` 索引的类型擦除资源实例。
    ///
    /// Resource slot table: type-erased resource instances keyed by `ResourceId`.
    resources: HashMap<ResourceId, Arc<dyn Any + Send + Sync>>,
    /// ID 到首个注册类型名的映射，仅用于 debug 构建中的碰撞检测。
    ///
    /// ID to first-registered type name, used for collision detection in
    /// debug builds only.
    #[cfg(debug_assertions)]
    id_names: HashMap<ResourceId, &'static str>,
}

impl ResourceManager {
    /// 创建一个空的资源管理器。
    ///
    /// Creates an empty resource manager.
    pub fn new() -> Self {
        Self {
            resources: HashMap::new(),
            #[cfg(debug_assertions)]
            id_names: HashMap::new(),
        }
    }

    /// 注册一个资源；若已存在同 ID 资源则覆盖。
    ///
    /// Registers a resource, overwriting any existing resource with the
    /// same ID.
    ///
    /// - `resource`: 要注册的资源实例
    pub fn add_resource<R: Resource + 'static + Send + Sync>(&mut self, resource: R) {
        let id = R::resource_id();
        #[cfg(debug_assertions)]
        {
            let name = std::any::type_name::<R>();
            match self.id_names.get(&id) {
                Some(existing) if *existing != name => {
                    // Same ResourceId but different Rust types: they would
                    // share one slot and cause type confusion, breaking
                    // get_lock's SAFETY precondition.
                    panic!(
                        "ResourceId collision: {existing} and {name} share {id:?} \
                         (layout-code collision, would cause type confusion)"
                    );
                }
                Some(_) => {}
                None => {
                    self.id_names.insert(id, name);
                }
            }
        }
        self.resources.insert(id, Arc::new(RwLock::new(resource)));
    }

    /// 移除某个类型的资源；不存在时无操作。
    ///
    /// Removes the resource of a type; a no-op if it is absent.
    pub fn remove_resource<R: Resource + 'static + Send + Sync>(&mut self) {
        self.resources.remove(&R::resource_id());
    }

    /// 获取资源槽的锁句柄（不加锁）；由调用方决定读或写。
    ///
    /// Fetches the lock handle of a resource slot (without locking). The caller picks read/write.
    pub(crate) fn get_lock<R: Resource + 'static + Send + Sync>(&self) -> Option<Arc<RwLock<R>>> {
        let erased = self.resources.get(&R::resource_id())?.clone();
        // SAFETY: a map hit means this side's R and the inserting side's R share
        // the same layout code, hence the same field names/field types/repr and
        // the same Arc<RwLock<R>> layout, so rebuilding Arc<RwLock<R>> from the
        // erased pointer is sound. Different layout codes never hit the map, so
        // there is no mis-reinterpretation path.
        let raw = Arc::into_raw(erased) as *const RwLock<R>;
        Some(unsafe { Arc::from_raw(raw) })
    }
}
